begin;
with j as (select * from jsonb_to_recordset($law7d0001$[{"code_id":"APK_RF","article_number":"1","version_date":"2002-07-24","article_text":"Правосудие в сфере предпринимательской и иной экономической деятельности осуществляется арбитражными судами в Российской Федерации, образованными в соответствии с Конституцией Российской Федерации и федеральным конституционным законом (далее - арбитражные суды), путем разрешения экономических споров и рассмотрения иных дел, отнесенных к их компетенции Арбитражным процессуальным кодексом Российской Федерации и другими федеральными законами, по правилам, установленным законодательством о судопроизводстве в арбитражных судах.","article_title":"Статья 1. Осуществление правосудия арбитражными судами","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"51f0a54fc0f49a7f24159a26a4c89d0487254c3cc2c945c3a49327bbbbe79a66"},{"code_id":"APK_RF","article_number":"10","version_date":"2002-07-24","article_text":"1. Арбитражный суд при разбирательстве дела обязан непосредственно исследовать все доказательства по делу.\n\n2. Доказательства, которые не были предметом исследования в судебном заседании, не могут быть положены арбитражным судом в основу принимаемого судебного акта.","article_title":"Статья 10. Непосредственность судебного разбирательства","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"0d29a78eed47d3a8d898c7409ec3ff647c1d0f4b2d7964e0edbf372e814d49b1"},{"code_id":"APK_RF","article_number":"100","version_date":"2002-07-24","article_text":"Правила об обеспечении иска, предусмотренные настоящей главой, применяются при обеспечении исполнения судебных актов.","article_title":"Статья 100. Обеспечение исполнения судебных актов","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"64d7dd83a116270c6d052264a70746537bec2d6bc8d6d096f2cf1ed282422611"},{"code_id":"APK_RF","article_number":"101","version_date":"2002-07-24","article_text":"Судебные расходы состоят из государственной пошлины и судебных издержек, связанных с рассмотрением дела арбитражным судом.","article_title":"Статья 101. Состав судебных расходов","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"8c6a156c79ca5e0ffca1d3aad14672e2b1d24fc9d7f64d7e4b5d318fffc546e8"},{"code_id":"APK_RF","article_number":"102","version_date":"2002-07-24","article_text":"Основания и порядок уплаты государственной пошлины, а также порядок предоставления отсрочки или рассрочки уплаты государственной пошлины устанавливаются в соответствии с законодательством Российской Федерации о налогах и сборах.\n\n(Статья в редакции Федерального закона от 02.11.2004 № 127-ФЗ)","article_title":"Статья 102. Уплата государственной пошлины","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"a15ef147f7654f4df0e8d2ce9fc45827758105698d55dbd88291d073a9b0a441"},{"code_id":"APK_RF","article_number":"103","version_date":"2002-07-24","article_text":"1. Цена иска определяется:\n\n1) по искам о взыскании денежных средств, исходя из взыскиваемой суммы;\n\n2) по искам о признании не подлежащим исполнению исполнительного или иного документа, по которому взыскание производится в бесспорном (безакцептном) порядке, исходя из оспариваемой денежной суммы;\n\n3) по искам об истребовании имущества, исходя из стоимости истребуемого имущества;\n\n4) по искам об истребовании земельного участка, исходя из стоимости земельного участка.\n\nВ цену иска включаются также указанные в исковом заявлении суммы неустойки (штраф, пени) и проценты.\n\nЦена иска, состоящего из нескольких самостоятельных требований, определяется суммой всех требований.\n\n2. По исковым заявлениям о признании права, в том числе права собственности, права пользования, права владения, права распоряжения, государственная пошлина уплачивается в размерах, установленных для исковых заявлений неимущественного характера.\n\n3. Цена иска указывается заявителем.\n\nВ случае неправильного указания заявителем цены иска она определяется арбитражным судом.","article_title":"Статья 103. Цена иска","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"a69ed8e4908838a31c50e939e0d25663c6baea7801cb6dabd6efe80786e61d8c"},{"code_id":"APK_RF","article_number":"104","version_date":"2002-07-24","article_text":"Основания и порядок возврата или зачета государственной пошлины устанавливаются в соответствии с законодательством Российской Федерации о налогах и сборах.\n\n(Статья в редакции Федерального закона от 02.11.2004 № 127-ФЗ)","article_title":"Статья 104. Основания и порядок возврата или зачета государственной пошлины","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"4113e91650ed5086d3929256e70ae44b3755d79f380baee367695ce87507e24b"},{"code_id":"APK_RF","article_number":"105","version_date":"2002-07-24","article_text":"Льготы по уплате государственной пошлины предоставляются в случаях и порядке, которые установлены законодательством Российской Федерации о налогах и сборах.\n\n(Статья в редакции Федерального закона от 02.11.2004 № 127-ФЗ)","article_title":"Статья 105. Льготы по уплате государственной пошлины","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"291bf3860364f284ea68d36cf2715a0b6a281f87af835054b9c358f9c381e2bb"},{"code_id":"APK_RF","article_number":"106","version_date":"2002-07-24","article_text":"К судебным издержкам, связанным с рассмотрением дела в арбитражном суде, относятся денежные суммы, подлежащие выплате экспертам, специалистам, свидетелям, переводчикам, расходы, связанные с проведением осмотра доказательств на месте, расходы на оплату услуг адвокатов и иных лиц, оказывающих юридическую помощь (представителей), расходы юридического лица на уведомление о корпоративном споре в случае, если федеральным законом предусмотрена обязанность такого уведомления, и другие расходы, понесенные лицами, участвующими в деле, в связи с рассмотрением дела в арбитражном суде. (В редакции федеральных законов от 19.07.2009 № 205-ФЗ; от 08.12.2011 № 422-ФЗ)","article_title":"Статья 106. Судебные издержки","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"d73b938dd7fda1208c11736b7bbdc8c50ab7f05fe2ce083a67d09352a9bf20cc"},{"code_id":"APK_RF","article_number":"107","version_date":"2002-07-24","article_text":"(Наименование в редакции Федерального закона от 08.12.2011 № 422-ФЗ)\n\nРазмер вознаграждения эксперту определяется судом по согласованию с лицами, участвующими в деле, и по соглашению с экспертом.\n\nРазмер вознаграждения переводчику определяется судом по соглашению с переводчиком.","article_title":"Статья 107. Денежные суммы, подлежащие выплате экспертам, специалистам, свидетелям и переводчикам","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"007ec7a2ac7502269f5c9346e7ad984ca9a63defe1884a9a46046880d9a4b734"},{"code_id":"APK_RF","article_number":"108","version_date":"2002-07-24","article_text":"1. Денежные суммы, подлежащие выплате экспертам и свидетелям, вносятся на депозитный счет арбитражного суда лицом, заявившим соответствующее ходатайство, в срок, установленный арбитражным судом. Если указанное ходатайство заявлено обеими сторонами, требуемые денежные суммы вносятся сторонами на депозитный счет арбитражного суда в равных частях.\n\n2. В случае, если в установленный арбитражным судом срок на депозитный счет арбитражного суда не были внесены денежные суммы, подлежащие выплате экспертам и свидетелям, арбитражный суд вправе отклонить ходатайство о назначении экспертизы и вызове свидетелей, если дело может быть рассмотрено и решение принято на основании других представленных сторонами доказательств.","article_title":"Статья 108. Внесение сторонами денежных сумм, необходимых для оплаты судебных издержек","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"2f7d485099b4f3ff0fb31680e757a674e76f8b9621a2f1ec66b7d8b12d1031d5"},{"code_id":"APK_RF","article_number":"109","version_date":"2002-07-24","article_text":"(Наименование в редакции Федерального закона от 08.12.2011 № 422-ФЗ)\n\nоплате услуг переводчика за счет средств федерального бюджета не распространяется на возмещение расходов на оплату услуг переводчика, понесенных иностранными лицами и лицами без гражданства, если иное не предусмотрено международным договором Российской Федерации.","article_title":"Статья 109. Выплата денежных сумм, причитающихся экспертам, специалистам, свидетелям и переводчикам","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"e4dfc7e582d9157f46379f4d58899ce154a6778146ca9fc6f1b8c8ad5d12b7e6"},{"code_id":"APK_RF","article_number":"11","version_date":"2002-07-24","article_text":"1. Разбирательство дел в арбитражных судах открытое.\n\n2. Разбирательство дела в закрытом судебном заседании допускается в случаях, если открытое разбирательство дела может привести к разглашению государственной тайны, в иных случаях, предусмотренных федеральным законом, а также при удовлетворении ходатайства лица, участвующего в деле и\n\nссылающегося на необходимость сохранения коммерческой, служебной или иной охраняемой законом тайны.\n\n3. Разглашение сведений, составляющих государственную, коммерческую, служебную или иную охраняемую законом тайну, влечет за собой ответственность, установленную федеральным законом.\n\n4. О разбирательстве дела в закрытом судебном заседании выносится определение. Определение выносится в отношении всего судебного разбирательства или его части.","article_title":"Статья 11. Гласность судебного разбирательства","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"81d6045d93589a3c4f6bed9aa9bf3de20dd4ab198223d69025ee300d7ddba6bc"},{"code_id":"APK_RF","article_number":"110","version_date":"2002-07-24","article_text":"1. Судебные расходы, понесенные лицами, участвующими в деле, в пользу которых принят судебный акт, взыскиваются арбитражным судом со стороны.\n\nВ случае, если иск удовлетворен частично, судебные расходы относятся на лиц, участвующих в деле, пропорционально размеру удовлетворенных исковых требований.\n\n2. Расходы на оплату услуг представителя, понесенные лицом, в пользу которого принят судебный акт, взыскиваются арбитражным судом с другого лица, участвующего в деле, в разумных пределах.\n\n3. Государственная пошлина, от уплаты которой в установленном порядке истец был освобожден, взыскивается с ответчика в доход федерального бюджета пропорционально размеру удовлетворенных исковых требований, если ответчик не освобожден от уплаты государственной пошлины.\n\n4. При соглашении лиц, участвующих в деле, о распределении судебных расходов арбитражный суд относит на них судебные расходы в соответствии с этим соглашением.\n\n5. Судебные расходы, понесенные лицами, участвующими в деле, в связи с рассмотрением апелляционной, кассационной жалобы, распределяются по правилам, установленным настоящей статьей.","article_title":"Статья 110. Распределение судебных расходов между лицами, участвующими в деле","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"990e7f57fda0196c1a167b855fb5165a9a88aa415aa94fa4278ab20a01b5d624"},{"code_id":"APK_RF","article_number":"111","version_date":"2002-07-24","article_text":"1. В случае, если спор возник вследствие нарушения лицом, участвующим в деле, претензионного или иного досудебного порядка урегулирования спора, предусмотренного федеральным законом или договором, в том числе нарушения срока представления ответа на претензию, оставления претензии без ответа, арбитражный суд относит на это лицо судебные расходы независимо от результатов рассмотрения дела.\n\n2. Арбитражный суд вправе отнести все судебные расходы по делу на лицо, злоупотребляющее своими процессуальными правами или не выполняющее своих процессуальных обязанностей, если это привело к срыву судебного заседания, затягиванию судебного процесса, воспрепятствованию рассмотрения дела и принятию законного и обоснованного судебного акта.\n\n3. По заявлению лица, участвующего в деле, на которое возлагается возмещение судебных расходов, арбитражный суд вправе уменьшить размер возмещения, если этим лицом представлены доказательства их чрезмерности.","article_title":"Статья 111. Отнесение судебных расходов на лицо, злоупотребляющее своими процессуальными правами","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"34a877c696463f985b1f3558768c9f002a669ac860dac9bcb5527be7cd2ffcc4"},{"code_id":"APK_RF","article_number":"112","version_date":"2002-07-24","article_text":"1. Вопросы распределения судебных расходов, отнесения судебных расходов на лицо, злоупотребляющее своими процессуальными правами, и другие вопросы о судебных расходах разрешаются арбитражным судом соответствующей судебной инстанции в судебном акте, которым заканчивается рассмотрение дела по существу, или в определении.\n\nПропущенный по уважительной причине срок подачи такого заявления может быть восстановлен судом.\n\nЗаявление по вопросу о судебных расходах рассматривается по правилам, предусмотренным статьей 159 настоящего Кодекса, с учетом особенностей, установленных главой 29 настоящего Кодекса. (В редакции  Федерального закона от 25.12.2023 № 667-ФЗ)\n\nПо результатам рассмотрения такого заявления выносится определение, которое может быть обжаловано.\n\n(Статья в редакции Федерального закона от 27.07.2010 № 228-ФЗ)","article_title":"Статья 112. Разрешение вопросов о судебных расходах","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"ed13fe069301da877ad44a6bae1483849a192a435b82bb1e2b85de69f0c96caa"},{"code_id":"APK_RF","article_number":"113","version_date":"2002-07-24","article_text":"1. Процессуальные действия совершаются в сроки, установленные настоящим Кодексом или иными федеральными законами, а в случаях, если процессуальные сроки не установлены, они назначаются арбитражным судом.\n\n2. Сроки совершения процессуальных действий определяются точной календарной датой, указанием на событие, которое обязательно должно наступить, или периодом, в течение которого действие может быть совершено.\n\n3. Процессуальные сроки исчисляются годами, месяцами и днями. В сроки, исчисляемые днями, не включаются нерабочие дни.\n\n4. Течение процессуального срока, исчисляемого годами, месяцами или днями, начинается на следующий день после календарной даты или дня наступления события, которыми определено начало процессуального срока.","article_title":"Статья 113. Установление и исчисление процессуальных сроков","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"1c8d3b6c4f3512427e3ab7b364731ca6af5586b12233cfe8694c83d42d714ade"},{"code_id":"APK_RF","article_number":"114","version_date":"2002-07-24","article_text":"1. Процессуальный срок, исчисляемый годами, истекает в соответствующий месяц и число последнего года установленного срока.\n\n2. Процессуальный срок, исчисляемый месяцами, истекает в соответствующее число последнего месяца установленного срока. Если окончание процессуального срока, исчисляемого месяцами, приходится на месяц, который соответствующего числа не имеет, срок истекает в последний день этого месяца.\n\n3. Процессуальный срок, исчисляемый днями, истекает в последний день установленного срока.\n\n4. В случаях, если последний день процессуального срока приходится на нерабочий день, днем окончания срока считается первый следующий за ним рабочий день.\n\n5. Процессуальное действие, для совершения которого установлен срок, может быть выполнено до двадцати четырех часов последнего дня установленного срока.\n\n6. Если заявление, жалоба, другие документы либо денежные суммы были сданы на почту, переданы или заявлены в орган либо уполномоченному их принять лицу до двадцати четырех часов последнего дня процессуального срока, срок не считается пропущенным.\n\n7. Если процессуальное действие должно быть совершено непосредственно в арбитражном суде или другой организации, срок истекает в тот час, когда в этом суде или этой организации по установленным правилам заканчивается рабочий день или прекращаются соответствующие операции.","article_title":"Статья 114. Окончание процессуальных сроков","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"f0bc1eb1a788586e9e70dac7df350c5a9e71bce2f195e4dc5701262122237b85"},{"code_id":"APK_RF","article_number":"115","version_date":"2002-07-24","article_text":"1. Лица, участвующие в деле, утрачивают право на совершение процессуальных действий с истечением процессуальных сроков, установленных настоящим Кодексом или иным федеральным законом либо арбитражным судом.\n\n2. Заявления, жалобы и другие поданные по истечении процессуальных сроков документы, если отсутствует ходатайство о восстановлении или продлении пропущенных сроков, не рассматриваются арбитражным судом и возвращаются лицам, которыми они были поданы.","article_title":"Статья 115. Последствия пропуска процессуальных сроков","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"46064efc9ff9c81a932bbee1675b96476b9d3e331688625be60de4b832f21b9c"},{"code_id":"APK_RF","article_number":"116","version_date":"2002-07-24","article_text":"1. Течение всех неистекших процессуальных сроков приостанавливается одновременно с приостановлением производства по делу.\n\n2. Со дня возобновления производства по делу течение процессуальных сроков продолжается.","article_title":"Статья 116. Приостановление процессуальных сроков","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"93fad423fd8b1f6ce66d8921b8a66224dc9c70e0256a9a03ddfb618b1e983bfa"},{"code_id":"APK_RF","article_number":"117","version_date":"2002-07-24","article_text":"1. Процессуальный срок подлежит восстановлению по ходатайству лица, участвующего в деле, если иное не предусмотрено настоящим Кодексом.\n\nВосстановление пропущенного процессуального срока арбитражным судом указывается в соответствующем судебном акте.\n\nКопия определения направляется лицу, обратившемуся с ходатайством, не позднее следующего дня после дня вынесения определения.","article_title":"Статья 117. Восстановление процессуальных сроков","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"9ddb14e1b0ae14ddf89f0572ea5c8b11cd273a390eba46592d41dc6950d1d52c"},{"code_id":"APK_RF","article_number":"118","version_date":"2002-07-24","article_text":"1. Назначенные арбитражным судом процессуальные сроки могут быть им продлены по заявлению лица, участвующего в деле, по правилам, предусмотренным статьей 117 настоящего Кодекса.\n\n2. Определение арбитражного суда об отказе в продлении назначенного им процессуального срока может быть обжаловано.","article_title":"Статья 118. Продление процессуальных сроков","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"5318030a6eec505cf5c96425d851f47ebb7b1931486b54ce5f2b300d166d9a67"},{"code_id":"APK_RF","article_number":"119","version_date":"2002-07-24","article_text":"(Статья в редакции Федерального закона от 19.07.2009 № 205-ФЗ)","article_title":"Статья 119. Наложение судебных штрафов","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"bcd71eed48f3dded8dab96cc5f46af72c3c3961669f6f84d71b16cf3be1bf94b"},{"code_id":"APK_RF","article_number":"12","version_date":"2002-07-24","article_text":"1. Судопроизводство в арбитражном суде ведется на русском языке - государственном языке Российской Федерации.\n\n2. Лицам, участвующим в деле и не владеющим русским языком, арбитражный суд разъясняет и обеспечивает право знакомиться с материалами дела, участвовать в судебных действиях, выступать в суде на родном языке или свободно выбранном языке общения и пользоваться услугами переводчика.","article_title":"Статья 12. Язык судопроизводства","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"7c7cd197793fb2e12bbc3510e81ce2ef27555286977902473bcc8f8422058467"},{"code_id":"APK_RF","article_number":"120","version_date":"2002-07-24","article_text":"1. Вопрос о наложении судебного штрафа на лицо, присутствующее в судебном заседании, разрешается в том же судебном заседании арбитражного суда.\n\n2. Вопрос о наложении судебного штрафа на лицо, не присутствующее в судебном заседании, разрешается в другом судебном заседании арбитражного суда.\n\n3. Лицо, в отношении которого рассматривается вопрос о наложении судебного штрафа, извещается о времени и месте судебного заседания с указанием оснований проведения судебного заседания. Неявка надлежащим образом извещенного лица не является препятствием к рассмотрению вопроса о наложении судебного штрафа.\n\n4. По результатам рассмотрения вопроса о наложении судебного штрафа арбитражный суд выносит определение.\n\nКопия определения о наложении судебного штрафа направляется лицу, на которое наложен штраф, в пятидневный срок со дня вынесения определения.\n\n5. Определение о наложении судебного штрафа приводится в исполнение немедленно в порядке, установленном для исполнения решения арбитражного суда.\n\nИсполнительный лист направляется арбитражным судом судебному приставу-исполнителю по месту жительства или адресу лица, на которое наложен судебный штраф. (В редакции Федерального закона от 28.11.2018 № 451-ФЗ)\n\n6. Определение арбитражного суда о наложении судебного штрафа может быть обжаловано в десятидневный срок со дня получения лицом, на которое наложен судебный штраф, копии определения.\n\n7. Подача жалобы на определение о наложении судебного штрафа не приостанавливает исполнение определения.","article_title":"Статья 120. Порядок рассмотрения вопроса о наложении судебного штрафа","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"351886b83fc62779064ff723f60a6d41e08cd9954cd1645eef51c88b1adeb854"},{"code_id":"APK_RF","article_number":"121","version_date":"2002-07-24","article_text":"1. Лица, участвующие в деле, и иные участники арбитражного процесса извещаются арбитражным судом о принятии искового заявления или заявления к производству и возбуждении производства по делу, о времени и месте судебного заседания или совершения отдельного процессуального действия путем направления копии судебного акта в порядке, установленном настоящим Кодексом, не позднее чем за пятнадцать дней до начала судебного заседания или совершения отдельного процессуального действия, если иное не предусмотрено настоящим Кодексом.\n\nИнформация о принятии искового заявления или заявления к производству, о времени и месте судебного заседания или совершения отдельного процессуального действия размещается арбитражным судом в установленном порядке в информационно-телекоммуникационной сети \"Интернет\" не позднее чем за пятнадцать дней до начала судебного заседания или совершения отдельного процессуального действия, если иное не предусмотрено настоящим Кодексом. Документы, подтверждающие размещение арбитражным судом в установленном порядке в информационно-телекоммуникационной сети \"Интернет\" указанных сведений, включая дату их размещения, приобщаются к материалам дела. (В редакции федеральных законов от 11.07.2011 № 200-ФЗ, от 30.12.2021 № 440-ФЗ)\n\n(Часть в редакции Федерального закона от 27.07.2010 № 228-ФЗ)\n\n2. Судебный акт, которым извещаются или вызываются участники арбитражного процесса, должен содержать:\n\n1) наименование и адрес арбитражного суда, адрес официального сайта в информационно-телекоммуникационной сети \"Интернет\", на котором размещается информация о деятельности арбитражного суда, номера телефонов арбитражного суда, адреса электронной почты, по которым лица, участвующие в деле, могут получить информацию о рассматриваемом деле; (В редакции федеральных законов от 27.07.2010 № 228-ФЗ, от 11.07.2011 № 200-ФЗ, от 30.12.2021 № 440-ФЗ)\n\n2) время и место судебного заседания или проведения отдельного процессуального действия;\n\n3) наименование лица, извещаемого или вызываемого в суд;\n\n4) наименование дела, по которому осуществляется извещение или вызов, а также указание, в качестве кого лицо вызывается;\n\n5) указание, какие действия и к какому сроку извещаемое или вызываемое лицо вправе или обязано совершить.\n\n3. В случаях, не терпящих отлагательства, арбитражный суд может известить или вызвать лиц, участвующих в деле, и иных участников арбитражного процесса телефонограммой, телеграммой, по факсимильной связи или электронной почте либо с использованием иных средств связи.\n\nСудебные извещения, адресованные гражданам, в том числе индивидуальным предпринимателям, направляются по месту их жительства. При этом место жительства индивидуального предпринимателя определяется на основании выписки из единого государственного реестра индивидуальных предпринимателей.\n\nЕсли лицо, участвующее в деле, ведет дело через представителя, судебное извещение направляется также по месту нахождения представителя.\n\nЕсли лицо, участвующее в деле, заявило ходатайство о направлении судебных извещений по иному адресу, арбитражный суд направляет судебное извещение также по этому адресу. В этом случае судебное извещение считается врученным лицу, участвующему в деле, если оно доставлено по указанному таким лицом адресу.\n\nСудебное извещение в электронном виде направляется участнику арбитражного процесса посредством единого портала государственных и муниципальных услуг либо системы электронного документооборота участника арбитражного процесса с использованием единой системы межведомственного электронного взаимодействия. (Дополнение абзацем - Федеральный закон от 30.12.2021 № 440-ФЗ)\n\nСудебное извещение по спору в отношении зарегистрированного результата интеллектуальной деятельности или средства индивидуализации направляется также по адресу для переписки, указанному в соответствующем государственном реестре. (Дополнение абзацем - Федеральный закон от 25.12.2023 № 667-ФЗ)\n\n(Часть в редакции Федерального закона от 27.07.2010 № 228-ФЗ)\n\nЛица, участвующие в деле, несут риск наступления неблагоприятных последствий в результате непринятия мер по получению информации о движении дела, если суд располагает информацией о том, что указанные лица надлежащим образом извещены о начавшемся процессе, за исключением случаев, когда лицами, участвующими в деле, меры по получению информации не могли быть приняты в силу чрезвычайных и непредотвратимых обстоятельств. (В редакции Федерального закона от 31.12.2014 № 527-ФЗ)\n\n(Дополнение частью - Федеральный закон от 27.07.2010 № 228-ФЗ)","article_title":"Статья 121. Судебные извещения","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"9e5cf0fefa052d69baae17dcb6e73747105e26b20519d4de34ecf429f55423b9"},{"code_id":"APK_RF","article_number":"122","version_date":"2002-07-24","article_text":"1. Копия судебного акта направляется арбитражным судом по почте заказным письмом с уведомлением о вручении либо путем вручения адресату под расписку непосредственно в арбитражном суде или по месту нахождения адресата, а в случаях, не терпящих отлагательства, путем направления телефонограммы, телеграммы, по факсимильной связи или электронной почте либо с использованием иных средств связи.\n\nСудебный акт в электронном виде направляется участнику арбитражного процесса посредством единого портала государственных и муниципальных услуг либо системы электронного документооборота участника арбитражного процесса с использованием единой системы межведомственного электронного взаимодействия. Если арбитражный суд располагает доказательствами получения лицами, участвующими в деле, и иными участниками арбитражного процесса определения о принятии искового заявления или заявления к производству и возбуждении производства по делу, информации о времени и месте первого судебного заседания, судебные акты, которыми назначаются время и место последующих судебных заседаний или совершения отдельных процессуальных действий, направляются лицам, участвующим в деле, и иным участникам арбитражного процесса посредством размещения этих судебных актов в информационной системе, определенной Верховным Судом Российской Федерации, Судебным департаментом при Верховном Суде Российской Федерации, в разделе, доступ к которому предоставляется лицам, участвующим в деле, и иным участникам арбитражного процесса (далее также - в режиме ограниченного доступа). Арбитражный суд также вправе известить указанных лиц о последующих судебных заседаниях или совершении отдельных процессуальных действий по делу путем направления телефонограммы, телеграммы, по факсимильной связи или электронной почте либо с использованием иных средств связи. (В редакции Федерального закона от 30.12.2021 № 440-ФЗ)\n\n(Часть в редакции Федерального закона от 27.07.2010 № 228-ФЗ)\n\n2. В случае, если копия судебного акта вручается адресату или его представителю непосредственно в арбитражном суде либо по месту их нахождения, такое вручение осуществляется под расписку.","article_title":"Статья 122. Порядок направления арбитражным судом копий судебных актов","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"e157b3ff76a53b1394f2292e5d45bb2d87337f8a70f7d9aef7ce726b66e44589"},{"code_id":"APK_RF","article_number":"123","version_date":"2002-07-24","article_text":"1. Лица, участвующие в деле, и иные участники арбитражного процесса считаются извещенными надлежащим образом, если к началу судебного заседания, совершения отдельного процессуального действия арбитражный суд располагает сведениями о получении адресатом копии определения о принятии искового заявления или заявления к производству и возбуждении производства по делу, направленной ему в порядке, установленном настоящим Кодексом, или иными доказательствами получения лицами, участвующими в деле, информации о начавшемся судебном процессе.\n\n2. Гражданин считается извещенным надлежащим образом, если судебное извещение вручено ему лично или совершеннолетнему лицу, проживающему совместно с этим гражданином, под расписку на подлежащем возврату в арбитражный суд уведомлении о вручении либо ином документе с указанием даты и времени вручения, а также источника информации.\n\n3. Судебное извещение, адресованное юридическому лицу, вручается лицу, уполномоченному на получение корреспонденции.\n\n4. Лица, участвующие в деле, и иные участники арбитражного процесса также считаются извещенными надлежащим образом арбитражным судом, если:\n\n1) адресат отказался от получения копии судебного акта и этот отказ зафиксирован организацией почтовой связи или арбитражным судом;\n\n2) несмотря на почтовое извещение, адресат не явился за получением копии судебного акта, направленной арбитражным судом в установленном порядке, о чем организация почтовой связи уведомила арбитражный суд;\n\n3) копия судебного акта не вручена в связи с отсутствием адресата по указанному адресу, о чем организация почтовой связи уведомила арбитражный суд с указанием источника данной информации;\n\n4) судебное извещение вручено уполномоченному лицу филиала или представительства юридического лица;\n\n5) судебное извещение вручено представителю лица, участвующего в деле;\n\n6) имеются доказательства вручения или направления судебного извещения в порядке, установленном частями 2 и 3 статьи 122 настоящего Кодекса;\n\n7) имеется подтверждение доставки судебного извещения посредством единого портала государственных и муниципальных услуг участнику арбитражного процесса, давшему согласие на едином портале государственных и муниципальных услуг на уведомление его посредством единого портала государственных и муниципальных услуг, или доставки судебного извещения посредством системы электронного документооборота участника арбитражного процесса с использованием единой системы межведомственного электронного взаимодействия. (Дополнение пунктом - Федеральный закон от 30.12.2021 № 440-ФЗ)\n\n(Статья в редакции Федерального закона от 27.07.2010 № 228-ФЗ)","article_title":"Статья 123. Надлежащее извещение","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"8ea53f7f23a9ecafd5baa1da9f76ff1517fc16d4fa001a8979c163e4e64291a7"},{"code_id":"APK_RF","article_number":"124","version_date":"2002-07-24","article_text":"1. Лица, участвующие в деле, обязаны сообщить арбитражному суду об изменении своего наименования. При отсутствии такого сообщения лицо, участвующее в деле, именуется в судебном акте исходя из последнего известного арбитражному суду наименования этого лица.\n\n2. Лица, участвующие в деле, обязаны сообщить арбитражному суду об изменении своего адреса во время производства по делу. При отсутствии такого сообщения копии судебных актов направляются по последнему известному арбитражному суду адресу и считаются доставленными, хотя бы адресат по этому адресу более не находится или не проживает.\n\n3. В случае, если лицо, участвующее в деле, сообщало арбитражному суду номера телефонов и факсов, адрес электронной почты или аналогичную информацию, оно должно проинформировать арбитражный суд об их изменении во время производства по делу.\n\n4. Арбитражный суд указывает в определении или протоколе судебного заседания изменение наименования лица, участвующего в деле, его адреса, номеров телефонов и факсов, адреса электронной почты или аналогичной информации.\n\n(Статья в редакции Федерального закона от 19.07.2009 № 205-ФЗ)\n\nРАЗДЕЛ II. ПРОИЗВОДСТВО В АРБИТРАЖНОМ СУДЕ ПЕРВОЙ ИНСТАНЦИИ. ИСКОВОЕ ПРОИЗВОДСТВО","article_title":"Статья 124. Изменение наименования лица, перемена адреса во время производства по делу","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"0eb59e04278baa1c3d742aef7160acd4b3ba72c2580007916bc8695310d2cc1f"},{"code_id":"APK_RF","article_number":"125","version_date":"2002-07-24","article_text":"1. Исковое заявление подается в арбитражный суд на бумажном носителе или в электронном виде, в том числе в форме электронного документа. Исковое заявление подписывается истцом или его представителем.\n\nИсковое заявление, подаваемое в электронном виде, содержащее ходатайство об обеспечении иска, должно быть подписано усиленной квалифицированной электронной подписью.\n\n(Часть в редакции Федерального закона от 30.12.2021 № 440-ФЗ)\n\n2. В исковом заявлении должны быть указаны:\n\n1) наименование арбитражного суда, в который подается исковое заявление;\n\n2) сведения об истце: для гражданина - фамилия, имя, отчество (при наличии), дата и место рождения, место жительства или место пребывания, место работы или дата и место государственной регистрации в качестве индивидуального предпринимателя и один из идентификаторов (страховой номер индивидуального лицевого счета, идентификационный номер налогоплательщика, серия и номер документа, удостоверяющего личность, серия и номер водительского удостоверения), номера телефонов, факсов, адреса электронной почты; для организации - наименование, адрес, идентификационный номер налогоплательщика, номера телефонов, факсов, адреса электронной почты; (В редакции Федерального закона от 21.12.2021 № 417-ФЗ)\n\n3) сведения об ответчике: для гражданина - фамилия, имя, отчество (при наличии), дата и место рождения, место жительства или место пребывания, место работы (если известно) и один из идентификаторов (страховой номер индивидуального лицевого счета, идентификационный номер налогоплательщика, серия и номер документа, удостоверяющего личность, основной государственный регистрационный номер индивидуального предпринимателя, серия и номер водительского удостоверения); для организации - наименование, адрес, идентификационный номер налогоплательщика и основной государственный регистрационный номер. В случае, если гражданину неизвестны дата и место рождения ответчика, один из его идентификаторов, об этом указывается в исковом заявлении и такая информация по запросу арбитражного суда предоставляется органами Фонда пенсионного и социального страхования Российской Федерации, и (или) налоговыми органами, и (или) органами внутренних дел. В этом случае срок принятия искового заявления к производству арбитражного суда, предусмотренный частью 1 статьи 127 настоящего Кодекса, исчисляется со дня получения арбитражным судом такой информации; (В редакции  федеральных законов от 21.12.2021 № 417-ФЗ, от 28.12.2022 № 569-ФЗ)\n\n4) требования истца к ответчику со ссылкой на законы и иные нормативные правовые акты, а при предъявлении иска к нескольким ответчикам - требования к каждому из них;\n\n5) обстоятельства, на которых основаны исковые требования, и подтверждающие эти обстоятельства доказательства;\n\n6) цена иска, если иск подлежит оценке;\n\n7) расчет взыскиваемой или оспариваемой денежной суммы;\n\n8) сведения о соблюдении истцом претензионного или иного досудебного порядка; (В редакции Федерального закона от 02.03.2016 № 47-ФЗ)\n\n81) сведения о предпринятых стороной (сторонами) действиях, направленных на примирение, если такие действия предпринимались; (Дополнение пунктом - Федеральный закон от 26.07.2019 № 197-ФЗ)\n\n9) сведения о мерах, принятых арбитражным судом по обеспечению имущественных интересов до предъявления иска;\n\n10) перечень прилагаемых документов.\n\nВ заявлении должны быть указаны и иные сведения, если они необходимы для правильного и своевременного рассмотрения дела, могут содержаться ходатайства, в том числе ходатайства об истребовании доказательств от ответчика или других лиц. (В редакции Федерального закона от 27.07.2010 № 228-ФЗ)","article_title":"Статья 125. Форма и содержание искового заявления","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"66da65bf5d0f0c06198671cc0f8eefc05f27b456743d70b621c75cd2954f1bfe"},{"code_id":"APK_RF","article_number":"126","version_date":"2002-07-24","article_text":"1) уведомление о вручении или иные документы, подтверждающие направление другим лицам, участвующим в деле, копий искового заявления и приложенных к нему документов, которые у других лиц, участвующих в деле, отсутствуют, в том числе в случае подачи в суд искового заявления и приложенных к нему документов в электронном виде; (В редакции Федерального закона от 30.12.2021 № 440-ФЗ)\n\n2) документ, подтверждающий уплату государственной пошлины в установленных порядке и в размере или право на получение льготы по уплате государственной пошлины, либо ходатайство о предоставлении отсрочки, рассрочки, об уменьшении размера государственной пошлины;\n\n3) документы, подтверждающие обстоятельства, на которых истец основывает свои требования;\n\n4) (Пункт утратил силу - Федеральный закон от 25.12.2023 № 667-ФЗ)\n\n5) доверенность или иные документы, подтверждающие полномочия на подписание искового заявления, а также копии документов о высшем юридическом образовании или об ученой степени по юридической специальности представителя, подписавшего исковое заявление, либо документов, удостоверяющих его статус адвоката, патентного поверенного, арбитражного управляющего, единоличного органа управления организации; (В редакции  Федерального закона от 25.12.2023 № 667-ФЗ)\n\n6) копии определения арбитражного суда об обеспечении имущественных интересов до предъявления иска;\n\n7) документы, подтверждающие соблюдение истцом претензионного или иного досудебного порядка, за исключением случаев, если его соблюдение не предусмотрено федеральным законом; (В редакции Федерального закона от 02.03.2016 № 47-ФЗ)\n\n71) документы, подтверждающие совершение стороной (сторонами) действий, направленных на примирение, если такие действия предпринимались и соответствующие документы имеются; (Дополнение пунктом - Федеральный закон от 26.07.2019 № 197-ФЗ)\n\n8) проект договора, если заявлено требование о понуждении заключить договор;\n\n9) выписка из единого государственного реестра юридических лиц или единого государственного реестра индивидуальных предпринимателей с указанием сведений о месте нахождения или месте жительства истца и ответчика и (или) приобретении физическим лицом статуса индивидуального предпринимателя либо прекращении физическим лицом деятельности в качестве индивидуального предпринимателя или иной документ, подтверждающий указанные сведения или отсутствие таковых. Такие документы должны быть получены не ранее чем за тридцать дней до дня обращения истца в арбитражный суд. (Дополнение пунктом - Федеральный закон от 27.07.2010 № 228-ФЗ)","article_title":"Статья 126. Документы, прилагаемые к исковому заявлению","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"e0c76b24c34a14168b4cc2b73bb2cd051b66829820de8a1c70408609582af3b5"},{"code_id":"APK_RF","article_number":"127","version_date":"2002-07-24","article_text":"1. Вопрос о принятии искового заявления к производству арбитражного суда решается судьей единолично в пятидневный срок со дня поступления искового заявления в арбитражный суд.\n\n2. Арбитражный суд обязан принять к производству исковое заявление, поданное с соблюдением требований, предъявляемых настоящим Кодексом к его форме и содержанию.\n\n3. О принятии искового заявления арбитражный суд выносит определение, которым возбуждается производство по делу.","article_title":"Статья 127. Принятие искового заявления и возбуждение производства по делу","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"592a07a1646ad3be3c3c7ae6f73d60a942cbcf86ccc551b009c574c7fda4f4f7"},{"code_id":"APK_RF","article_number":"127.1","version_date":"2002-07-24","article_text":"1. Судья отказывает в принятии искового заявления, заявления, если:\n\n1) исковое заявление, заявление подлежат рассмотрению в порядке конституционного или уголовного судопроизводства либо не подлежат рассмотрению в судах; (В редакции Федерального закона от 28.11.2018 № 451-ФЗ)\n\n2) имеются вступивший в законную силу принятый по спору между теми же лицами, о том же предмете и по тем же основаниям судебный акт арбитражного суда, суда общей юрисдикции или компетентного суда иностранного государства, за исключением случаев, если арбитражный суд отказал в признании и приведении в исполнение решения иностранного суда, а также определение о прекращении производства по делу в связи с принятием отказа истца от иска или утверждением мирового соглашения сторон либо определение об отказе в принятии искового заявления, заявления;\n\n3) имеется ставшее обязательным для сторон и принятое по спору между теми же сторонами, о том же предмете и по тем же основаниям решение третейского суда, за исключением случаев, если арбитражный суд отказал в выдаче исполнительного листа на принудительное исполнение решения третейского суда либо если арбитражный суд отменил указанное решение.\n\n2. Судья Суда по интеллектуальным правам отказывает в принятии заявления об оспаривании нормативного правового акта либо акта, содержащего разъяснения законодательства и обладающего нормативными свойствами, в случае, если имеется вступившее в законную силу решение арбитражного суда или суда общей юрисдикции по ранее рассмотренному делу, проверившего по тем же основаниям соответствие оспариваемого нормативного правового акта иному нормативному правовому акту, имеющему большую юридическую силу, либо проверившего по тем же основаниям оспариваемый акт, содержащий разъяснения законодательства и обладающий нормативными свойствами.\n\n3. Об отказе в принятии искового заявления, заявления судья выносит определение, в котором указывает обстоятельства, послужившие основанием для отказа в принятии искового заявления, заявления, и решает вопрос о возврате государственной пошлины лицу, предъявившему исковое заявление, заявление, если государственная пошлина была уплачена. Копия определения вместе с исковым заявлением, заявлением и прилагаемыми к нему документами направляется указанному лицу не позднее пяти дней со дня поступления искового заявления, заявления в суд.\n\n4. Отказ в принятии искового заявления, заявления препятствует повторному обращению в суд с такими заявлениями к тому же ответчику, о том же предмете и по тем же основаниям.\n\n5. Определение арбитражного суда об отказе в принятии искового заявления, заявления может быть обжаловано.\n\nВ случае отмены определения об отказе в принятии искового заявления, заявления такие заявления считаются поданными в день первоначального обращения в арбитражный суд.\n\n(Дополнение статьей - Федеральный закон от 19.12.2016 № 435-ФЗ)","article_title":"Статья 127.1. Отказ в принятии искового заявления, заявления","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"3a51bb11b7bb6bfa393f3443ebf61c1dfc83004be94713ffb678ecfd7ad791a2"},{"code_id":"APK_RF","article_number":"128","version_date":"2002-07-24","article_text":"1. Арбитражный суд, установив при рассмотрении вопроса о принятии искового заявления к производству, что оно подано с нарушением требований, установленных статьями 125 и 126 настоящего Кодекса, выносит определение об оставлении заявления без движения.\n\n2. В определении арбитражный суд указывает основания для оставления искового заявления без движения и срок, в течение которого истец должен устранить обстоятельства, послужившие основанием для\n\nоставления искового заявления без движения.\n\nКопия определения об оставлении искового заявления без движения направляется истцу не позднее следующего дня после дня его вынесения.\n\n3. В случае, если обстоятельства, послужившие основанием для оставления искового заявления без движения, будут устранены в срок, установленный в определении арбитражного суда, заявление считается поданным в день его первоначального поступления в суд и принимается к производству арбитражного суда.\n\n4. В случае, если указанные в части 2 настоящей статьи обстоятельства не будут устранены в срок, установленный в определении, арбитражный суд возвращает исковое заявление и прилагаемые к нему документы в порядке, предусмотренном статьей 129 настоящего Кодекса.","article_title":"Статья 128. Оставление искового заявления без движения","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"1bb085de35495a00e3c921dd63eb186fef0cec2f8a22095d494a0f7489927e49"},{"code_id":"APK_RF","article_number":"129","version_date":"2002-07-24","article_text":"1. Арбитражный суд возвращает исковое заявление, если при рассмотрении вопроса о принятии заявления установит, что:\n\n1) дело неподсудно данному арбитражному суду или подсудно суду общей юрисдикции; (В редакции Федерального закона от 28.11.2018 № 451-ФЗ)\n\n2) (Пункт утратил силу - Федеральный закон от 19.07.2009 № 205-ФЗ)\n\n21) заявленные требования подлежат рассмотрению в порядке приказного производства; (Дополнение пунктом - Федеральный закон от 23.06.2016 № 220-ФЗ)\n\n3) до вынесения определения о принятии искового заявления к производству арбитражного суда от истца поступило ходатайство о возвращении заявления;\n\n4) не устранены обстоятельства, послужившие основаниями для оставления искового заявления без движения, в срок, установленный в определении суда;\n\n5) истцом не соблюден претензионный или иной досудебный порядок урегулирования спора с ответчиком, если такой порядок является обязательным в силу закона; (Дополнение пунктом - Федеральный закон от 02.03.2016 № 47-ФЗ)\n\n6) исковое заявление не подписано или исковое заявление подписано  лицом, не имеющим полномочий на его подписание. (Дополнение пунктом - Федеральный закон от 28.11.2018 № 451-ФЗ) (В редакции Федерального закона от 02.12.2019 № 406-ФЗ)\n\nАрбитражный суд также возвращает исковое заявление, если отклонено ходатайство о предоставлении отсрочки, рассрочки уплаты государственной пошлины, об уменьшении ее размера.\n\n2. О возвращении искового заявления арбитражный суд выносит определение.\n\nВ определении указываются основания для возвращения заявления, решается вопрос о возврате государственной пошлины из федерального бюджета.\n\n3. Копия определения о возвращении искового заявления направляется истцу не позднее следующего дня после дня вынесения определения или после истечения срока, установленного судом для устранения обстоятельств, послуживших основанием для оставления заявления без движения, вместе с заявлением и прилагаемыми к нему документами.\n\n4. Определение арбитражного суда о возвращении искового заявления может быть обжаловано.\n\n5. В случае отмены определения исковое заявление считается поданным в день первоначального обращения в арбитражный суд.\n\n6. Возвращение искового заявления не препятствует повторному обращению с таким же требованием в арбитражный суд в общем порядке после устранения обстоятельств, послуживших основанием для его возвращения.","article_title":"Статья 129. Возвращение искового заявления","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"61b583bab63927a6fcfc88e92869864d4ce27fc3e68e5fbddb46863302bc0510"},{"code_id":"APK_RF","article_number":"13","version_date":"2002-07-24","article_text":"1. Арбитражные суды рассматривают дела на основании Конституции Российской Федерации, международных договоров Российской Федерации, федеральных конституционных законов, федеральных законов, нормативных правовых актов Президента Российской Федерации и нормативных правовых актов Правительства Российской Федерации, нормативных правовых актов федеральных органов исполнительной власти, конституций (уставов), законов и иных нормативных правовых актов субъектов Российской Федерации, актов органов местного самоуправления.\n\nАрбитражные суды в случаях, предусмотренных федеральным законом, применяют обычаи делового оборота.\n\n2. Арбитражный суд, установив при рассмотрении дела несоответствие нормативного правового акта иному имеющему большую юридическую силу нормативному правовому акту, в том числе издание его с превышением полномочий, принимает судебный акт в соответствии с нормативным правовым актом, имеющим большую юридическую силу.\n\n3. Если при рассмотрении конкретного дела арбитражный суд придет к выводу о несоответствии закона, примененного или подлежащего применению в рассматриваемом деле, Конституции Российской Федерации, арбитражный суд обращается в Конституционный Суд Российской Федерации с запросом о проверке конституционности этого закона.","article_title":"Статья 13. Нормативные правовые акты, применяемые при рассмотрении дел","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"5e1d65e6d88d045156e65ce9a44f9c000cd866afc7117fb1def5632eaffc08e9"},{"code_id":"APK_RF","article_number":"130","version_date":"2002-07-24","article_text":"1. Истец вправе соединить в одном заявлении несколько требований, связанных между собой по основаниям возникновения или представленным доказательствам.\n\n2. Арбитражный суд первой инстанции вправе объединить несколько однородных дел, в которых участвуют одни и те же лица, в одно производство для совместного рассмотрения.","article_title":"Статья 130. Соединение и разъединение нескольких требований","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"a48c3df1d1096c20c1e9e91b67f1923e80dc77e6ceff5f365f5cf7526a52b170"},{"code_id":"APK_RF","article_number":"131","version_date":"2002-07-24","article_text":"1. Ответчик обязан направить или представить в арбитражный суд и лицам, участвующим в деле, отзыв на исковое заявление с указанием возражений относительно предъявленных к нему требований по каждому доводу, содержащемуся в исковом заявлении.\n\nТакой отзыв и прилагаемые к нему документы могут быть представлены в арбитражный суд на бумажном носителе или в электронном виде, в том числе в форме электронного документа. (Дополнение абзацем - Федеральный закон от 27.07.2010 № 228-ФЗ) (В редакции Федерального закона от 30.12.2021 № 440-ФЗ)\n\n2. В случаях и в порядке, которые установлены настоящим Кодексом, иные участники арбитражного процесса вправе направить в арбитражный суд и другим лицам, участвующим в деле, отзыв в письменной форме на исковое заявление.\n\nОтветчик направляет отзыв на исковое заявление на бумажном носителе в арбитражный суд и лицам, участвующим в деле, заказным письмом с уведомлением о вручении. Отзыв на исковое заявление в электронном виде направляется лицам, участвующим в деле, посредством единого портала государственных и муниципальных услуг либо системы электронного документооборота участника арбитражного процесса с использованием единой системы межведомственного электронного взаимодействия. (Дополнение абзацем - Федеральный закон от 30.12.2021 № 440-ФЗ)\n\n1) наименование истца, его адрес или, если истцом является гражданин, его место жительства; (В редакции Федерального закона от 28.11.2018 № 451-ФЗ)\n\n2) наименование ответчика, его адрес или, если ответчиком является гражданин, его место жительства, дата и место рождения, место работы или дата и место государственной регистрации в качестве индивидуального предпринимателя; (В редакции Федерального закона от 28.11.2018 № 451-ФЗ)\n\n3) возражения относительно каждого довода, касающегося существа заявленных требований, со ссылкой на законы и иные нормативные правовые акты, а также на доказательства, обосновывающие возражения;\n\n31) сведения о предпринятых ответчиком действиях, направленных на примирение, если такие действия предпринимались; (Дополнение пунктом - Федеральный закон от 26.07.2019 № 197-ФЗ)\n\n32) мнение ответчика о возможности примирения сторон; (Дополнение пунктом - Федеральный закон от 26.07.2019 № 197-ФЗ)\n\n4) перечень прилагаемых к отзыву документов, в том числе подтверждающих совершение ответчиком действий, направленных на примирение, если такие действия предпринимались и соответствующие документы имеются. (В редакции Федерального закона от 26.07.2019 № 197-ФЗ)\n\n(Статья в редакции Федерального закона от 19.07.2009 № 205-ФЗ)","article_title":"Статья 131. Отзыв на исковое заявление","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"cc6602f6b17eec5626b71757116987274c5af2184fc7500e17eedb1131c0b22d"},{"code_id":"APK_RF","article_number":"132","version_date":"2002-07-24","article_text":"1. Ответчик до принятия арбитражным судом первой инстанции судебного акта, которым заканчивается рассмотрение дела по существу, вправе предъявить истцу встречный иск для рассмотрения его совместно с первоначальным иском.\n\n2. Предъявление встречного иска осуществляется по общим правилам предъявления исков.\n\n3. Встречный иск принимается арбитражным судом в случае, если:\n\n1) встречное требование направлено к зачету первоначального требования;\n\n2) удовлетворение встречного иска исключает полностью или в части удовлетворение первоначального иска;\n\n3) между встречным и первоначальным исками имеется взаимная связь и их совместное рассмотрение приведет к более быстрому и правильному рассмотрению дела.\n\n4. Арбитражный суд возвращает встречный иск, если отсутствуют условия, предусмотренные частью 3 настоящей статьи, по правилам статьи 129 настоящего Кодекса.","article_title":"Статья 132. Предъявление встречного иска","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"b56e2820a171cce36fd1e11f428655cfe9b41ef1adde7237d4316c029772809a"},{"code_id":"APK_RF","article_number":"133","version_date":"2002-07-24","article_text":"1. Задачами подготовки дела к судебному разбирательству являются определение характера спорного правоотношения и подлежащего применению законодательства, обстоятельств, имеющих значение для правильного рассмотрения дела; разрешение вопроса о составе лиц, участвующих в деле, и других участников арбитражного процесса; оказание содействия лицам, участвующим в деле, в представлении необходимых доказательств; примирение сторон.\n\n2. Подготовка дела к судебному разбирательству проводится судьей единолично по каждому находящемуся в производстве арбитражного суда первой инстанции делу в целях обеспечения его правильного и своевременного рассмотрения.\n\n(Статья в редакции Федерального закона от 19.07.2009 № 205-ФЗ)","article_title":"Статья 133. Задачи подготовки дела к судебному разбирательству","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"0bd525880ef4c1904113e9f25750144c1d7a28abf44943a58e84d1f3667913c0"},{"code_id":"APK_RF","article_number":"134","version_date":"2002-07-24","article_text":"1. Арбитражный суд первой инстанции после принятия заявления к производству выносит определение о подготовке дела к судебному разбирательству и указывает сторонам на возможность заявить ходатайство о рассмотрении дела с участием арбитражных заседателей, обратиться за содействием к суду или посреднику, в том числе медиатору, судебному примирителю, в целях урегулирования спора или использовать другие примирительные процедуры, а также на действия, которые надлежит совершить лицам, участвующим в деле, и сроки совершения этих действий.\n\nВ целях урегулирования спора судья принимает меры для примирения сторон, в том числе может предложить сторонам использовать какую-либо примирительную процедуру, отложить проведение предварительного судебного заседания, совершение других подготовительных действий.\n\nНа подготовку дела к судебному разбирательству может быть указано в определении о принятии заявления к производству.\n\n(Часть в редакции Федерального закона от 26.07.2019 № 197-ФЗ)\n\n2. Подготовка дела к судебному разбирательству проводится в срок, определяемый судьей с учетом обстоятельств конкретного дела и необходимости совершения соответствующих процессуальных действий, и завершается проведением предварительного судебного заседания, если в соответствии с настоящим Кодексом не установлено иное.\n\n(Статья в редакции Федерального закона от 19.07.2009 № 205-ФЗ)","article_title":"Статья 134. Срок подготовки дела к судебному разбирательству","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"0a65fbfdeb1daa31926001690ec33ea96a5d96efbe83a5ecc5d54a74634bc3aa"},{"code_id":"APK_RF","article_number":"135","version_date":"2002-07-24","article_text":"1. При подготовке дела к судебному разбирательству судья:\n\n1) вызывает стороны и (или) их представителей и проводит с ними собеседование в целях выяснения обстоятельств, касающихся существа заявленных требований и возражений; предлагает раскрыть доказательства, их подтверждающие, и представить при необходимости дополнительные доказательства в определенный срок; разъясняет сторонам их права и обязанности, последствия совершения или несовершения процессуальных действий в установленный срок; определяет по согласованию со сторонами сроки представления необходимых доказательств и проведения предварительного судебного заседания;\n\n2) разъясняет сторонам их право на рассмотрение дела с участием арбитражных заседателей, право передать спор на разрешение третейского суда, право обратиться на любой стадии арбитражного процесса в целях урегулирования спора за содействием к посреднику, в том числе медиатору, судебному примирителю, использовать другие примирительные процедуры, разъясняет условия и порядок реализации данного права, существо и преимущества примирительных процедур, а также последствия совершения таких действий, принимает меры для заключения сторонами мирового соглашения, содействует примирению сторон; (В редакции Федерального закона от 26.07.2019 № 197-ФЗ)\n\n3) оказывает содействие сторонам в получении необходимых доказательств, истребует по ходатайству сторон, а в случаях, предусмотренных настоящим Кодексом, по своей инициативе необходимые доказательства, разрешает вопросы о назначении экспертизы, вызове в судебное заседание экспертов, свидетелей, привлечении переводчика, специалиста, необходимости осмотра на месте письменных и вещественных доказательств, а также принимает иные меры для представления сторонами доказательств; (В редакции Федерального закона от 08.12.2011 № 422-ФЗ)\n\n4) по ходатайству сторон разрешает вопросы об обеспечении иска, о предоставлении встречного обеспечения, а также об обеспечении доказательств, направляет судебные поручения;\n\n5) рассматривает вопросы о вступлении в дело других лиц, замене ненадлежащего ответчика, соединении и разъединении нескольких требований, принятии встречного иска, возможности проведения выездного судебного заседания;\n\n6) совершает иные направленные на обеспечение правильного и своевременного рассмотрения дела действия.\n\n2. Действия по подготовке дела к судебному разбирательству совершаются судьей в порядке, предусмотренном настоящим Кодексом.\n\n3. Суд выносит определение о переходе к рассмотрению дела в порядке упрощенного производства в случае, если при подготовке к судебному разбирательству дела истцом заявлено ходатайство о рассмотрении дела в порядке упрощенного производства и в арбитражный суд представлено согласие ответчика на рассмотрение дела в порядке упрощенного производства или суд по своей инициативе предлагает рассмотреть дело в порядке упрощенного производства и при согласии сторон выносит соответствующее определение.\n\nОдновременно с указанным определением сторонам направляются данные, необходимые для идентификации сторон, в целях доступа к материалам дела в электронном виде.\n\nИсковое заявление, заявление по данному делу размещаются в установленном порядке в информационно-телекоммуникационной сети \"Интернет\" в режиме ограниченного доступа не позднее следующего дня после дня вынесения указанного определения. (В редакции федеральных законов от 23.06.2016 № 220-ФЗ, от 30.12.2021 № 440-ФЗ)\n\n(Дополнение частью - Федеральный закон от 25.06.2012 № 86-ФЗ)","article_title":"Статья 135. Действия по подготовке дела к судебному разбирательству","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"613cc6477db77fe4cabaff1a6785f6d037f869ccebd36a0c6c6be51ded199f20"},{"code_id":"APK_RF","article_number":"136","version_date":"2002-07-24","article_text":"При неявке в предварительное судебное заседание надлежащим образом извещенных истца и (или) ответчика, других заинтересованных лиц, которые могут быть привлечены к участию в деле, заседание проводится в их отсутствие.\n\n1) разрешает ходатайства сторон;\n\n2) определяет достаточность представленных доказательств, доводит до сведения сторон, какие доказательства имеются в деле;\n\n21) выясняет мнение сторон о возможности урегулировать спор, предлагает сторонам использовать примирительные процедуры; при выявлении намерения сторон обратиться к судебному примирителю суд утверждает его кандидатуру, выбранную сторонами, в порядке, установленном настоящим Кодексом; (Дополнение пунктом - Федеральный закон от 26.07.2019 № 197-ФЗ)\n\n3) выносит на рассмотрение вопросы, разрешаемые при подготовке дела к судебному разбирательству, и совершает предусмотренные настоящим Кодексом иные процессуальные действия.\n\nтву лиц, участвующих в деле, вправе объявить перерыв в предварительном судебном заседании на срок не более пяти дней для представления ими дополнительных доказательств.","article_title":"Статья 136. Предварительное судебное заседание","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"86c67f0cdfa63c53fd89949527cd9ff21087b9c1441d09575986903e5937a5b9"},{"code_id":"APK_RF","article_number":"137","version_date":"2002-07-24","article_text":"1. Судья, признав дело подготовленным, выносит определение о назначении дела к судебному разбирательству.\n\n2. В определении о назначении дела к судебному разбирательству указывается на окончание подготовки дела к судебному разбирательству и разрешение вопросов о привлечении к делу третьих лиц, принятие встречного иска, соединение или разъединение нескольких требований, привлечение арбитражных заседателей, а также на разрешение других вопросов, если по ним не были вынесены соответствующие определения, время и место проведения судебного заседания в арбитражном суде первой инстанции.\n\n3. Копии определения о назначении дела к судебному разбирательству направляются лицам, участвующим в деле.","article_title":"Статья 137. Назначение дела к судебному разбирательству","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"4868312f81d6ca81ba370f34bf352e721e105558da57a798eba4f72144d0a4d8"},{"code_id":"APK_RF","article_number":"138","version_date":"2002-07-24","article_text":"1. Арбитражный суд принимает меры для примирения сторон, содействует им в урегулировании спора, руководствуясь при этом интересами сторон и задачами судопроизводства в арбитражных судах.\n\n2. Примирение сторон осуществляется на основе принципов добровольности, сотрудничества, равноправия и конфиденциальности.\n\n3. Стороны пользуются равными правами на выбор примирительной процедуры, определение условий ее проведения, а также кандидатуры посредника, в том числе медиатора, судебного примирителя. По указанным вопросам сторонами может быть заключено соглашение.\n\n4. Примирение сторон возможно на любой стадии арбитражного процесса и при исполнении судебного акта, если иное не предусмотрено настоящим Кодексом и иным федеральным законом.\n\n(Статья в редакции Федерального закона от 26.07.2019 № 197-ФЗ)","article_title":"Статья 138. Примирение сторон","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"9fea06e5c40001d6908762c3727897fd744ce509c3ec83bf0dd17fa645779722"},{"code_id":"APK_RF","article_number":"138.1","version_date":"2002-07-24","article_text":"1. Примирительная процедура может быть проведена по ходатайству сторон (стороны) либо по предложению арбитражного суда.\n\nПредложение арбитражного суда провести примирительную процедуру может содержаться в определении о принятии искового заявления (заявления) к производству, о подготовке дела к судебному разбирательству или в ином определении по делу, а также может быть сделано судом в устной форме.\n\nДля рассмотрения сторонами вопроса о возможности использовать примирительную процедуру арбитражный суд может объявить перерыв в судебном заседании.\n\n2. В случае согласия сторон с предложением арбитражного суда о проведении примирительной процедуры, удовлетворения ходатайства о проведении примирительной процедуры сторон или одной стороны при согласии другой стороны, а также в случае, предусмотренном частью 2 статьи 190 настоящего Кодекса, арбитражный суд выносит определение о проведении примирительной процедуры и при необходимости об отложении судебного разбирательства.\n\nВ определении о проведении примирительной процедуры арбитражный суд указывает наименования сторон, предмет спора и круг вопросов, для урегулирования которых может быть использована примирительная процедура, сроки проведения примирительной процедуры.\n\nВ определении о проведении примирительной процедуры могут содержаться и иные указания, необходимые для обеспечения надлежащего проведения примирительной процедуры.\n\n3. Примирительная процедура должна быть завершена в срок, установленный судом в определении о проведении примирительной процедуры. По ходатайству сторон указанный срок может быть продлен арбитражным судом.\n\n4. В ходе использования примирительной процедуры стороны могут достичь результатов примирения, установленных настоящим Кодексом.\n\n5. В случае, если стороны не достигли примирения, отказались от проведения примирительных процедур либо истек срок их проведения, арбитражный суд возобновляет судебное разбирательство в порядке, установленном частью 10 статьи 158 настоящего Кодекса.\n\n(Дополнение статьей - Федеральный закон от 26.07.2019 № 197-ФЗ)","article_title":"Статья 138.1. Порядок и сроки проведения примирительной процедуры","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"bc93519f423b0c4bfcee5db223225fb69840c8ce1d0f22fca3502e514857a150"},{"code_id":"APK_RF","article_number":"138.2","version_date":"2002-07-24","article_text":"Споры могут быть урегулированы путем проведения переговоров, посредничества, в том числе медиации, судебного примирения, или использования других примирительных процедур, если это не противоречит федеральному закону.\n\n(Дополнение статьей - Федеральный закон от 26.07.2019 № 197-ФЗ)","article_title":"Статья 138.2. Виды примирительных процедур","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"f2201b23ada1bc7be5e2490803dc8f362588f51dd106d0e4c37b126e948e1411"},{"code_id":"APK_RF","article_number":"138.3","version_date":"2002-07-24","article_text":"1. Стороны вправе урегулировать спор путем проведения переговоров в целях примирения.\n\n2. Переговоры осуществляются на условиях, определяемых сторонами.\n\n3. В случаях, предусмотренных федеральным законом или договором, переговоры проводятся в обязательном порядке.\n\n(Дополнение статьей - Федеральный закон от 26.07.2019 № 197-ФЗ)","article_title":"Статья 138.3. Переговоры","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"ff16d0e662b6a9f4dab114530ddaf94c1f6c6974d16d83af660378b543c35a77"},{"code_id":"APK_RF","article_number":"138.4","version_date":"2002-07-24","article_text":"1. Стороны вправе урегулировать спор путем применения процедуры медиации в порядке, установленном настоящим Кодексом и федеральным законом.\n\n2. В случае заявления сторонами соответствующего ходатайства арбитражный суд откладывает судебное разбирательство на основании части 2 статьи 158 настоящего Кодекса.\n\n(Дополнение статьей - Федеральный закон от 26.07.2019 № 197-ФЗ)","article_title":"Статья 138.4. Медиация","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"82f979e6de7cf96e19ba1e8a96f75e08a8c320b5057b7f1fcd32e695b2437ffa"}]$law7d0001$::jsonb) as x(code_id text,article_number text,version_date date,article_text text,article_title text,amendment_eo_number text,amendment_date date,is_current boolean,is_repealed boolean,repealed_date date,text_hash text))
insert into law7_mirror.article_versions(code_id,article_number,version_date,article_text,article_title,amendment_eo_number,amendment_date,is_current,is_repealed,repealed_date,text_hash,source_commit,imported_at)
select code_id,article_number,version_date,article_text,article_title,amendment_eo_number,amendment_date,is_current,is_repealed,repealed_date,text_hash,'70a1d8fc6b27b67ad7f12f03f017d02b5f68a0c895447159039800965895f8b2',now() from j
on conflict (code_id,article_number,version_date) do update set article_text=excluded.article_text,article_title=excluded.article_title,amendment_eo_number=excluded.amendment_eo_number,amendment_date=excluded.amendment_date,is_current=excluded.is_current,is_repealed=excluded.is_repealed,repealed_date=excluded.repealed_date,text_hash=excluded.text_hash,source_commit=excluded.source_commit,imported_at=now();
commit;
